165				svc: ChatQuotaService,
166				turnId: string,
167				nanoAiu: number,
168				delayMs: number = 0
169			): Promise<void> {
170				if (delayMs > 0) {
171					await new Promise(resolve => setTimeout(resolve, delayMs));
172				}
173				svc.setLastCopilotUsage(nanoAiu, turnId);
174			}
175	
176			/**
177			 * Simulates a full agent turn:
178			 * 1. resetTurnCredits (turn start)
179			 * 2. N API calls with timing
180			 * 3. getCreditsForTurn (turn complete → display)
181			 */
182			async function simulateTurn(
183				svc: ChatQuotaService,
184				turnId: string,
185				calls: { nanoAiu: number; delayMs: number }[]
186			): Promise<number | undefined> {
187				svc.resetTurnCredits(turnId);
188				for (const call of calls) {
189					await simulateApiCall(svc, turnId, call.nanoAiu, call.delayMs);
190				}
191				return svc.getCreditsForTurn(turnId);
192			}
