	/**
	 * Checks whether a quota/rate-limit info has crossed a *new* threshold
	 * since the baseline was established.
	 *
	 * The first data arrival only establishes a baseline: any threshold that
	 * is already exceeded is recorded without producing a warning. Only a
	 * subsequent transition from below a threshold to at-or-above it — after
	 * the baseline exists — yields a warning. A threshold is never re-shown
	 * within a session; the baseline is reset only on sign-out.
	 */
	private _checkThreshold(info: IChatQuota | undefined, tracker: IThresholdTracker): { percentUsed: number; resetDate: Date } | undefined {
		if (!info || info.unlimited) {
			return undefined;
		}

		const percentUsed = 100 - info.percentRemaining;

		// First data arrival: establish a baseline without notifying, even if
		// one or more thresholds are already exceeded.
		if (!tracker.baselined) {
			tracker.baselined = true;
			for (const threshold of THRESHOLDS) {
				if (percentUsed >= threshold) {
					tracker.shown.add(threshold);
				}
			}
			return undefined;
		}

		// Walk thresholds highest-first so we report the most severe newly
		// crossed threshold.
		for (let i = THRESHOLDS.length - 1; i >= 0; i--) {
			const threshold = THRESHOLDS[i];
			if (percentUsed >= threshold && !tracker.shown.has(threshold)) {
				// Mark this and all lower thresholds as shown
				for (let j = 0; j <= i; j++) {
					tracker.shown.add(THRESHOLDS[j]);
				}
				return { percentUsed: Math.floor(percentUsed), resetDate: info.resetDate };
			}
		}
		return undefined;
	}

